mapper.select:
SELECT
     AS bucket_start,
    #{window} AS window_type,
    tenant_id AS tenant_id,
    knowledge_base_id AS knowledge_base_id,
    query_type AS query_type,
    retrieval_mode AS retrieval_mode,
    llm_model AS llm_model,
    embedding_model AS embedding_model,
    status AS status,
    SUM(query_count) AS query_count,
    SUM(success_count) AS success_count,
    SUM(failed_count) AS failed_count,
    SUM(prompt_tokens) AS prompt_tokens,
    SUM(completion_tokens) AS completion_tokens,
    SUM(total_tokens) AS total_tokens,
    SUM(estimated_total_cost) AS estimated_total_cost,
    AVG(p50_latency_ms) AS p50_latency_ms,
    AVG(p90_latency_ms) AS p90_latency_ms
FROM ${table}
WHERE window_type = #{sourceWindow}

    AND tenant_id = #{tenantId}


    AND knowledge_base_id = #{knowledgeBaseId}


    AND query_type = #{queryType}


    AND retrieval_mode = #{retrievalMode}


    AND status = #{status}


    AND llm_model = #{llmModel}


    AND embedding_model = #{embeddingModel}


    AND bucket_start >= #{from}


    AND bucket_start < #{to}

GROUP BY , tenant_id, knowledge_base_id, query_type, retrieval_mode,
         llm_model, embedding_model, status
ORDER BY bucket_start ASC

SELECT
     AS bucket_start,
    #{window} AS window_type,
    tenant_id AS tenant_id,
    knowledge_base_id AS knowledge_base_id,
    retrieval_mode AS retrieval_mode,
    query_type AS query_type,
    feedback_rating AS feedback_rating,
    feedback_status AS feedback_status,
    assignee AS assignee,
    SUM(query_count) AS query_count,
    SUM(feedback_count) AS feedback_count,
    SUM(helpful_count) AS helpful_count,
    SUM(not_helpful_count) AS not_helpful_count,
    SUM(correction_count) AS correction_count
FROM ${table}
WHERE window_type = #{sourceWindow}

    AND tenant_id = #{tenantId}


    AND knowledge_base_id = #{knowledgeBaseId}


    AND retrieval_mode = #{retrievalMode}


    AND query_type = #{queryType}


    AND feedback_rating = #{feedbackRating}


    AND feedback_status = #{feedbackStatus}


    AND assignee = #{assignee}


    AND bucket_start >= #{from}


    AND bucket_start < #{to}

GROUP BY , tenant_id, knowledge_base_id, retrieval_mode, query_type,
         feedback_rating, feedback_status, assignee
ORDER BY bucket_start ASC

SELECT
     AS bucket_start,
    #{window} AS window_type,
    tenant_id AS tenant_id,
    provider AS provider,
    model AS model,
    api_key_hash AS api_key_hash,
    error_code AS error_code,
    degraded_reason AS degraded_reason,
    SUM(request_count) AS request_count,
    SUM(success_count) AS success_count,
    SUM(failure_count) AS failure_count,
    SUM(fallback_count) AS fallback_count,
    SUM(total_tokens) AS total_tokens,
    SUM(estimated_cost) AS estimated_cost,
    AVG(p50_latency_ms) AS p50_latency_ms,
    AVG(p90_latency_ms) AS p90_latency_ms,
    AVG(p99_latency_ms) AS p99_latency_ms
FROM ${table}
WHERE window_type = #{sourceWindow}

    AND tenant_id = #{tenantId}


    AND provider = #{provider}


    AND model = #{model}


    AND api_key_hash = #{apiKeyHash}


    AND error_code = #{errorCode}


    AND degraded_reason = #{degradedReason}


    AND bucket_start >= #{from}


    AND bucket_start < #{to}

GROUP BY , tenant_id, provider, model, api_key_hash, error_code,
         degraded_reason
ORDER BY bucket_start ASC
